/**
 * Maps a Unicode codepoint to its font Glyph ID (GID).
 */
export function getGlyphId(code: number): number {
  for (let i = 0; i < FONT_SEGMENTS.length; i++) {
    const [start, end, delta] = FONT_SEGMENTS[i];
    if (code >= start && code <= end) {
      return (code + delta) & 0xffff;
    }
  }
  return 0; // .notdef
}

/**
 * Encodes a Unicode string into a PDF hex string for Identity-H CID font rendering.
 */
export function encodePdfHexString(text: string): string {
  let hex = "";
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i);
    const gid = getGlyphId(code);
    hex += gid.toString(16).padStart(4, "0");
  }
  return "<" + hex + ">";
}
